      "name": "ticket_open_state",
      "causal_role": "collider",
      "named_in_query": false,
      "rationale": "Whether the ticket is still open is downstream of / jointly determined by resolution progress; conditioning on open-state relative to resolution time risks selection/collider bias, not a confounder."
    }
